import { Context } from '/private/tmp/bench-full/runs/probe-command-review/src/context'

const req = new Request('http://localhost/')

function show(label: string, res: Response) {
  let sc: string[] | undefined
  try { sc = (res.headers as any).getSetCookie?.() } catch {}
  console.log(label, '| set-cookie get:', JSON.stringify(res.headers.get('set-cookie')), '| getSetCookie:', JSON.stringify(sc))
}

// Scenario 1: setCookie-like header on prepared headers, then direct c.res assignment
{
  const c = new Context(req)
  c.header('Set-Cookie', 'a=1; Path=/', { append: true })
  c.res = new Response('body')
  show('S1 prepared set-cookie then c.res=', c.res)
}

// Scenario 2: old #res cookies vs new response cookies on reassignment
{
  const c = new Context(req)
  const r1 = new Response(null)
  r1.headers.append('set-cookie', 'old=1; Path=/')
  r1.headers.append('set-cookie', 'old=2; Path=/')
  c.res = r1
  const r2 = new Response('new', { headers: { 'set-cookie': 'new=1; Path=/' } })
  c.res = r2
  show('S2 reassign with new cookies', c.res)
}

// Scenario 3: old #res cookies + c.text() (newResponse path)
{
  const c = new Context(req)
  const r1 = new Response(null)
  r1.headers.append('set-cookie', 'old=1; Path=/')
  r1.headers.append('set-cookie', 'old2=2; Path=/')
  c.res = r1
  show('S3 c.text after c.res', c.text('hi'))
}

// Scenario 4: context set-cookie + arg Response set-cookie in #newResponse
{
  const c = new Context(req)
  c.header('Set-Cookie', 'ctx=1; Path=/', { append: true })
  const orig = new Response('', { headers: { 'set-cookie': 'resp=1; Path=/' } })
  show('S4 c.body with arg Response', c.body('', orig))
}

// Scenario 5: c.header after finalized + bodyUsed (no recreate)
{
  const c = new Context(req)
  c.res = new Response('bar')
  await c.res.text()
  try {
    c.header('X-Custom', 'Message')
    console.log('S5 header after bodyUsed OK, x-custom =', c.res.headers.get('x-custom'))
  } catch (e) {
    console.log('S5 threw:', (e as Error).message)
  }
}
EOF
